SELECT * FROM agri_prod_alert_rule
WHERE deleted = 0
AND tenant_id = #{tenantId}
AND rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')
AND alert_type = #{dto.alertType}
ORDER BY create_time DESC

SELECT * FROM agri_prod_alert_rule
WHERE rule_code = #{ruleCode} AND deleted = 0
AND tenant_id = #{tenantId}
